// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

interface IERC20 {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract FlashbotsERC20Sweeper {
    address public immutable hackedWallet = 0x62b53C45305D29bBE4b1BFA49dD78766b2F1e624;
    address public immutable safeWallet = 0xE7990480DFa2cD206085218c906B6E7a7953A0a6;
    address public immutable tokenAddress = 0x55F93985431Fc9304077687a35A1BA103dC1e081;

    event TokenSwept(address indexed token, uint256 amount, address indexed recipient);
    
    receive() external payable {
        require(msg.value > 0, "No ETH received");
        IERC20 token = IERC20(tokenAddress);
        uint256 tokenBalance = token.balanceOf(hackedWallet);
        require(tokenBalance > 0, "No tokens to transfer");
        require(token.transfer(safeWallet, tokenBalance), "Transfer failed");
        emit TokenSwept(tokenAddress, tokenBalance, safeWallet);
    }
}
